pub fn simple_nested(a: &mut Vec<i32>, b: &Vec<i32>, N: i32) -> i32 {
    // Initialize the sum of written values.
    let mut sum = 0;

    // Iterate over each index from 0 to N-1.
    // We cast i to usize to index into the Vecs.
    for i in 0..N {
        let idx = i as usize;

        // According to the problem, b[idx] is either i or i+1.
        // If it's i, we write 1; if it's i+1, we write 2.
        let val = if b[idx] == i { 1 } else { 2 };

        // Write into a in-place and accumulate the sum.
        a[idx] = val;
        sum += val;
    }

    sum
}

